    XEventManager.AddEventListener(XEventId.EVENT_FINISH_TASK, self.RefreshCurTabTasks, self)
    XEventManager.AddEventListener(XEventId.EVENT_TASK_SYNC, self.RefreshCurTabTasks, self)
