    XEventManager.RemoveEventListener(XEventId.EVENT_FINISH_TASK, self.RefreshCurTabTasks, self)
    XEventManager.RemoveEventListener(XEventId.EVENT_TASK_SYNC, self.RefreshCurTabTasks, self)
